/**
 * User Profile Settings component
 *
 * Allows users to:
 * - View their profile information
 * - Change their password
 * - Upload a profile picture (avatar)
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import type { ChangeEvent } from 'react';
import { useProfile } from '../../hooks/useProfile';
import { useAuth } from '../../hooks/useAuth';
import { useReferral } from '../../hooks/useReferral';
import { useCedrosLogin } from '../../context/useCedrosLogin';
import { PasswordInput } from '../email/PasswordInput';
import { LoadingSpinner } from '../shared/LoadingSpinner';
import { ErrorMessage } from '../shared/ErrorMessage';
import { validatePassword } from '../../utils/validation';
import { getInitials } from './profileHelpers';

export interface UserProfileSettingsProps {
  /** Called when password is changed successfully */
  onPasswordChange?: () => void;
  /** Called when user requests to close/cancel */
  onClose?: () => void;
  /** Additional CSS class */
  className?: string;
}

type SettingsView = 'main' | 'change-password';

/**
 * User profile settings panel.
 *
 * Shows user profile information and provides controls for
 * changing password and managing profile settings.
 *
 * @example
 * ```tsx
 * function SettingsPage() {
 *   return (
 *     <UserProfileSettings
 *       onPasswordChange={() => console.log('Password changed')}
 *       onClose={() => navigate('/dashboard')}
 *     />
 *   );
 * }
 * ```
 */
export function UserProfileSettings({
  onPasswordChange,
  onClose,
  className = '',
}: UserProfileSettingsProps) {
  const { user, refreshUser } = useAuth();
  const { config, _internal } = useCedrosLogin();
  const { isLoading, error, changePassword, updateProfile, clearError } = useProfile();

  const [view, setView] = useState<SettingsView>('main');
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [isUploadingAvatar, setIsUploadingAvatar] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Payout wallet state
  const [payoutWallet, setPayoutWallet] = useState<string>(user?.payoutWalletAddress ?? '');
  const [isSavingWallet, setIsSavingWallet] = useState(false);
  const [walletSuccess, setWalletSuccess] = useState(false);
  const [walletError, setWalletError] = useState<string | null>(null);

  const handleSavePayoutWallet = useCallback(async () => {
    const trimmed = payoutWallet.trim();
    if (trimmed.length > 0 && (trimmed.length < 32 || trimmed.length > 44)) {
      setWalletError('Invalid Solana address — must be 32–44 characters.');
      return;
    }
    const base58Regex = /^[1-9A-HJ-NP-Za-km-z]+$/;
    if (trimmed.length > 0 && !base58Regex.test(trimmed)) {
      setWalletError('Invalid Solana address — contains non-base58 characters.');
      return;
    }
    setWalletError(null);
    setIsSavingWallet(true);
    try {
      await updateProfile({ payoutWalletAddress: trimmed || undefined });
      await refreshUser();
      setWalletSuccess(true);
      setTimeout(() => setWalletSuccess(false), 2000);
    } catch (err) {
      setWalletError(err instanceof Error ? err.message : 'Failed to save payout wallet');
    } finally {
      setIsSavingWallet(false);
    }
  }, [payoutWallet, updateProfile, refreshUser]);

  // Referral state
  const { getReferral, regenerateCode, isLoading: isReferralLoading } = useReferral();
  const [referralCode, setReferralCode] = useState<string | null>(null);
  const [referralCount, setReferralCount] = useState<number>(0);
  const [referralCopied, setReferralCopied] = useState(false);
  const [showPayoutWallet, setShowPayoutWallet] = useState(false);

  useEffect(() => {
    getReferral()
      .then((info) => {
        setReferralCode(info.referralCode);
        setReferralCount(info.referralCount);
        setShowPayoutWallet(info.directPayoutEnabled);
      })
      .catch(() => {
        // Referral feature may not be enabled — silently ignore
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Password validation
  const passwordValidation = validatePassword(newPassword);
  const passwordsMatch = newPassword === confirmPassword;
  const canSubmitPassword =
    currentPassword.length > 0 &&
    newPassword.length > 0 &&
    confirmPassword.length > 0 &&
    passwordValidation.isValid &&
    passwordsMatch;

  const handleAvatarUpload = useCallback(
    async (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      setActionError(null);
      setIsUploadingAvatar(true);

      try {
        const formData = new FormData();
        formData.append('file', file);

        const token = _internal?.getAccessToken?.();
        const headers: Record<string, string> = {};
        if (token) {
          headers['Authorization'] = `Bearer ${token}`;
        }

        const response = await fetch(`${config.serverUrl}/auth/upload/avatar`, {
          method: 'POST',
          headers,
          body: formData,
          credentials: 'include',
        });

        if (!response.ok) {
          const body = await response.json().catch(() => null);
          throw new Error(body?.message || body?.error || `Upload failed (${response.status})`);
        }

        // Refresh user context to pick up new picture URL
        await refreshUser();
      } catch (err) {
        setActionError(err instanceof Error ? err.message : 'Failed to upload avatar');
      } finally {
        setIsUploadingAvatar(false);
        // Reset file input so the same file can be re-selected
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
      }
    },
    [config.serverUrl, _internal, refreshUser]
  );

  const handlePasswordChange = useCallback(async () => {
    if (!canSubmitPassword) return;

    setActionError(null);
    setSuccessMessage(null);

    try {
      await changePassword({
        currentPassword,
        newPassword,
      });

      // Clear form and show success
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setSuccessMessage('Password changed successfully. Other sessions have been logged out.');
      onPasswordChange?.();

      // Return to main view after short delay
      setTimeout(() => {
        setView('main');
        setSuccessMessage(null);
      }, 2000);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to change password');
    }
  }, [canSubmitPassword, currentPassword, newPassword, changePassword, onPasswordChange]);

  const handleCancelPasswordChange = useCallback(() => {
    setView('main');
    setCurrentPassword('');
    setNewPassword('');
    setConfirmPassword('');
    setActionError(null);
    clearError();
  }, [clearError]);

  // Change Password view
  if (view === 'change-password') {
    return (
      <div className={`cedros-profile-settings ${className}`}>
        <div className="cedros-profile-panel">
          <h3 className="cedros-profile-title">Change password</h3>
          <p className="cedros-profile-description">
            Enter your current password and choose a new one. This will log you out of other
            devices.
          </p>

          {(actionError || error) && (
            <div className="cedros-profile-error">
              <ErrorMessage
                error={{ code: 'UNKNOWN_ERROR', message: actionError || error?.message || '' }}
                onDismiss={() => {
                  setActionError(null);
                  clearError();
                }}
              />
            </div>
          )}

          {successMessage && (
            <div className="cedros-profile-success">
              <span className="cedros-profile-success-icon">&#10003;</span>
              {successMessage}
            </div>
          )}

          <div className="cedros-profile-form">
            <div className="cedros-profile-field">
              <PasswordInput
                label="Current password"
                placeholder="Enter your current password"
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                disabled={isLoading}
                autoFocus
              />
            </div>

            <div className="cedros-profile-field">
              <PasswordInput
                label="New password"
                placeholder="Enter new password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                disabled={isLoading}
                showStrengthMeter
              />
            </div>

            <div className="cedros-profile-field">
              <PasswordInput
                label="Confirm new password"
                placeholder="Confirm new password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                disabled={isLoading}
                error={
                  confirmPassword.length > 0 && !passwordsMatch
                    ? 'Passwords do not match'
                    : undefined
                }
              />
            </div>
          </div>

          <div className="cedros-profile-actions">
            <button
              type="button"
              className="cedros-button cedros-button-outline cedros-button-md"
              onClick={handleCancelPasswordChange}
              disabled={isLoading}
            >
              Cancel
            </button>
            <button
              type="button"
              className="cedros-button cedros-button-primary cedros-button-md"
              onClick={handlePasswordChange}
              disabled={isLoading || !canSubmitPassword}
            >
              {isLoading ? (
                <>
                  <LoadingSpinner size="sm" />
                  <span>Changing...</span>
                </>
              ) : (
                'Change password'
              )}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Main profile view
  return (
    <div className={`cedros-profile-settings ${className}`}>
      <div className="cedros-profile-panel">
        <div className="cedros-profile-header">
          <div
            className="cedros-profile-avatar-container cedros-profile-avatar-container--clickable"
            onClick={() => fileInputRef.current?.click()}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                fileInputRef.current?.click();
              }
            }}
            aria-label="Change profile picture"
          >
            {isUploadingAvatar ? (
              <div className="cedros-profile-avatar cedros-profile-avatar-fallback">
                <LoadingSpinner size="sm" />
              </div>
            ) : user?.picture ? (
              <img
                src={user.picture}
                alt={user.name || 'Profile'}
                className="cedros-profile-avatar"
              />
            ) : (
              <div className="cedros-profile-avatar cedros-profile-avatar-fallback">
                {getInitials(user)}
              </div>
            )}
            <div className="cedros-profile-avatar-overlay">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" />
                <circle cx="12" cy="13" r="4" />
              </svg>
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/jpeg,image/png,image/gif,image/webp"
              onChange={handleAvatarUpload}
              className="cedros-profile-avatar-input"
              aria-hidden="true"
              tabIndex={-1}
            />
          </div>
          <div className="cedros-profile-info">
            <h3 className="cedros-profile-name">{user?.name || 'User'}</h3>
            <p className="cedros-profile-email">{user?.email}</p>
          </div>
        </div>

        <div className="cedros-profile-section">
          <h4 className="cedros-profile-section-title">Account</h4>

          <div className="cedros-profile-row">
            <div className="cedros-profile-row-content">
              <span className="cedros-profile-row-label">Email</span>
              <span className="cedros-profile-row-value">{user?.email || 'Not set'}</span>
            </div>
          </div>

          <div className="cedros-profile-row">
            <div className="cedros-profile-row-content">
              <span className="cedros-profile-row-label">Password</span>
              <span className="cedros-profile-row-value">••••••••</span>
            </div>
            <button
              type="button"
              className="cedros-button cedros-button-outline cedros-button-sm"
              onClick={() => setView('change-password')}
            >
              Change
            </button>
          </div>
        </div>

        {referralCode && (
          <div className="cedros-profile-section">
            <h4 className="cedros-profile-section-title">Referral</h4>
            <div className="cedros-profile-row">
              <div className="cedros-profile-row-content">
                <span className="cedros-profile-row-label">Your code</span>
                <span className="cedros-profile-row-value cedros-profile-row-value--mono">
                  {referralCode}
                </span>
              </div>
              <button
                type="button"
                className="cedros-button cedros-button-outline cedros-button-sm"
                onClick={() => {
                  navigator.clipboard.writeText(referralCode);
                  setReferralCopied(true);
                  setTimeout(() => setReferralCopied(false), 2000);
                }}
              >
                {referralCopied ? 'Copied' : 'Copy'}
              </button>
            </div>
            <div className="cedros-profile-row">
              <div className="cedros-profile-row-content">
                <span className="cedros-profile-row-label">Referrals</span>
                <span className="cedros-profile-row-value">{referralCount}</span>
              </div>
              <button
                type="button"
                className="cedros-button cedros-button-outline cedros-button-sm"
                onClick={async () => {
                  try {
                    const newCode = await regenerateCode();
                    setReferralCode(newCode);
                  } catch {
                    // error handled by hook
                  }
                }}
                disabled={isReferralLoading}
              >
                {isReferralLoading ? 'Regenerating...' : 'Regenerate'}
              </button>
            </div>
          </div>
        )}

        {showPayoutWallet && <div className="cedros-profile-section">
          <h4 className="cedros-profile-section-title">Payout wallet</h4>
          <p className="cedros-profile-description">
            Solana wallet address to receive direct referral payouts when enabled by the platform.
          </p>
          <div className="cedros-profile-row cedros-profile-row--column">
            <input
              type="text"
              className="cedros-input"
              placeholder="Solana wallet address (base58)"
              value={payoutWallet}
              onChange={(e: ChangeEvent<HTMLInputElement>) => {
                setPayoutWallet(e.target.value);
                setWalletError(null);
              }}
              disabled={isSavingWallet}
              maxLength={44}
            />
            {walletError && (
              <span className="cedros-profile-error-text">{walletError}</span>
            )}
            {walletSuccess && (
              <span className="cedros-profile-success-text">Saved.</span>
            )}
          </div>
          <div className="cedros-profile-actions">
            <button
              type="button"
              className="cedros-button cedros-button-primary cedros-button-sm"
              onClick={handleSavePayoutWallet}
              disabled={isSavingWallet}
            >
              {isSavingWallet ? 'Saving...' : 'Save wallet'}
            </button>
          </div>
        </div>}

        {onClose && (
          <div className="cedros-profile-footer">
            <button
              type="button"
              className="cedros-button cedros-button-outline cedros-button-md"
              onClick={onClose}
            >
              Close
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
