/**
 * Token quick-select bar with "Custom" fallback for multi-token deposit steps.
 * Renders quick-action buttons plus a full TokenSelector dropdown on demand.
 */
import { useMemo, useState } from 'react';
import { TokenSelector } from '../TokenSelector';
import type { Token } from '../tokens';
import { OTHER_TOKEN } from './tokenUtils';

interface TokenQuickSelectorProps {
  token: Token;
  tokens: Token[];
  quickActionSymbols: string[];
  customTokenSymbols: string[];
  onTokenSelect: (token: Token) => void;
}

export function TokenQuickSelector({
  token,
  tokens,
  quickActionSymbols,
  customTokenSymbols,
  onTokenSelect,
}: TokenQuickSelectorProps) {
  const [showCustomToken, setShowCustomToken] = useState(false);
  const [customOpenSignal, setCustomOpenSignal] = useState(0);

  const customTokens = useMemo(() => {
    const baseTokens =
      customTokenSymbols.length === 0
        ? tokens
        : tokens.filter((candidate) => customTokenSymbols.includes(candidate.symbol));
    const resolved = baseTokens.length > 0 ? baseTokens : tokens;
    const hasOther = resolved.some((candidate) => candidate.symbol === OTHER_TOKEN.symbol);
    return hasOther ? resolved : [...resolved, OTHER_TOKEN];
  }, [tokens, customTokenSymbols]);

  return (
    <div className="cedros-deposit-flow-field">
      <label className="cedros-deposit-flow-label">Token</label>
      <div className="cedros-deposit-flow-token-quick">
        {quickActionSymbols.map((symbol) => {
          const quickToken = tokens.find((candidate) => candidate.symbol === symbol);
          const isActive = token.symbol === symbol;
          return (
            <button
              key={symbol}
              type="button"
              className={`cedros-deposit-flow-token-quick-btn ${isActive ? 'is-active' : ''}`}
              onClick={() => {
                if (quickToken) {
                  setShowCustomToken(false);
                  onTokenSelect(quickToken);
                }
              }}
              disabled={!quickToken}
            >
              {quickToken?.logoUrl && (
                <img
                  className="cedros-deposit-flow-token-quick-icon"
                  src={quickToken.logoUrl}
                  alt={`${symbol} logo`}
                />
              )}
              {symbol}
            </button>
          );
        })}
        <button
          type="button"
          className={`cedros-deposit-flow-token-quick-btn ${showCustomToken ? 'is-active' : ''}`}
          onClick={() => {
            setShowCustomToken(true);
            setCustomOpenSignal((current) => current + 1);
          }}
        >
          Custom
        </button>
      </div>
      {showCustomToken && (
        <div className="cedros-deposit-flow-token-custom">
          <TokenSelector
            tokens={customTokens}
            selectedToken={token}
            onSelect={onTokenSelect}
            openSignal={customOpenSignal}
          />
        </div>
      )}
    </div>
  );
}
