import solLogo from '../../../assets/tokens/sol.webp';
import { getDisplayDecimals, type Token } from '../tokens';
import type { DepositConfigResponse } from '../../../types/deposit';
import type { CurrencyMode } from './types';

export const LAMPORTS_PER_SOL = 1_000_000_000;
export const MAX_DEPOSIT_USD = 10_000;

/**
 * SOL token definition for SOL-only mode
 */
