export interface Token {
  /** Token mint address */
  mint: string;
  /** Token symbol (e.g., SOL, USDC) */
  symbol: string;
  /** Token name (e.g., Solana, USD Coin) */
  name: string;
  /** Token decimals */
  decimals: number;
  /** Token logo URL */
  logoUrl?: string;
}

/**
 * Supported stablecoins for deposits
 */
/** Look up decimals for a currency symbol. Falls back to 6 (stablecoin default). */
export function getDecimalsForCurrency(currency: string): number {
  const upper = currency.toUpperCase();
  const token = SUPPORTED_TOKENS.find((t) => t.symbol === upper);
  return token?.decimals ?? 6;
}

/** Display-appropriate decimal places for a token symbol (M-08).
 * M-18: Accepts optional on-chain decimals for custom tokens not in SUPPORTED_TOKENS.
 */
export function getDisplayDecimals(symbol: string, onChainDecimals?: number): number {
  const upper = symbol.toUpperCase();
  const token = SUPPORTED_TOKENS.find((t) => t.symbol === upper);
  const decimals = token?.decimals ?? onChainDecimals;
  if (decimals === undefined) return 2;
  // SOL: 4 display decimals (standard in ecosystem)
  if (upper === 'SOL') return 4;
  // Stablecoins: 2 display decimals (they represent fiat)
  if (decimals === 6 && upper !== 'SOL') return 2;
  // High-decimal tokens like ORE (11): cap at 6 for readability
  if (decimals > 6) return 6;
  // Everything else: use on-chain decimals (e.g., BONK=5)
  return decimals;
}

