import { useEffect, useState, useCallback } from 'react';
import { useRewards } from '../hooks/useRewards';

// ---- helpers ----------------------------------------------------------------

function formatAmount(amount: number, currency: string): string {
  if (currency === 'SOL') return (amount / 1_000_000_000).toFixed(4) + ' SOL';
  return '$' + (amount / 1_000_000).toFixed(2);
}

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return iso;
  }
}

const BASE58_RE = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/;

function isValidBase58Address(value: string): boolean {
  return BASE58_RE.test(value);
}

function triggerLabel(triggerType: string): string {
  switch (triggerType) {
    case 'signup':
      return 'Sign-up';
    case 'spend':
      return 'Spend';
    case 'first_spend':
      return 'First Spend';
    default:
      return triggerType;
  }
}

// ---- status badge -----------------------------------------------------------

interface StatusBadgeProps {
  status: string;
}

function StatusBadge({ status }: StatusBadgeProps) {
  const modifierMap: Record<string, string> = {
    pending: 'cedros-rewards-panel__badge--pending',
    completed: 'cedros-rewards-panel__badge--completed',
    failed: 'cedros-rewards-panel__badge--failed',
    credited: 'cedros-rewards-panel__badge--credited',
  };
  const modifier = modifierMap[status] ?? 'cedros-rewards-panel__badge--pending';
  return (
    <span className={`cedros-rewards-panel__badge ${modifier}`}>
      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  );
}

// ---- props ------------------------------------------------------------------

export interface RewardsPanelProps {
  /** Solana explorer URL base (default: https://explorer.solana.com) */
  explorerUrl?: string;
  /** Additional CSS class */
  className?: string;
}

// ---- component --------------------------------------------------------------

const PAGE_SIZE = 10;

/**
 * Self-contained rewards dashboard panel.
 *
 * Shows a summary of earned rewards, pending payouts, referral count,
 * a payout wallet editor (for direct_payout mode), and a paginated history
 * table with Solana explorer links.
 *
 * @example
 * ```tsx
 * <RewardsPanel explorerUrl="https://explorer.solana.com" />
 * ```
 */
export function RewardsPanel({ explorerUrl = 'https://explorer.solana.com', className }: RewardsPanelProps) {
  const {
    rewards,
    history,
    historyTotal,
    fetchRewards,
    fetchHistory,
    setPayoutWallet,
    isLoading,
    error,
  } = useRewards();

  // pagination
  const [page, setPage] = useState(0);

  // wallet form
  const [walletInput, setWalletInput] = useState('');
  const [walletError, setWalletError] = useState<string | null>(null);
  const [walletSaving, setWalletSaving] = useState(false);
  const [walletSaved, setWalletSaved] = useState(false);

  // load on mount
  useEffect(() => {
    fetchRewards().catch(() => undefined);
    fetchHistory(PAGE_SIZE, 0).catch(() => undefined);
  }, [fetchRewards, fetchHistory]);

  // sync wallet input when rewards load
  useEffect(() => {
    if (rewards?.payoutWalletAddress != null) {
      setWalletInput(rewards.payoutWalletAddress);
    }
  }, [rewards?.payoutWalletAddress]);

  // page change
  const handlePageChange = useCallback(
    (newPage: number) => {
      setPage(newPage);
      fetchHistory(PAGE_SIZE, newPage * PAGE_SIZE).catch(() => undefined);
    },
    [fetchHistory]
  );

  const totalPages = Math.ceil(historyTotal / PAGE_SIZE);

  // wallet save
  const handleWalletSave = useCallback(async () => {
    const trimmed = walletInput.trim();
    if (trimmed !== '' && !isValidBase58Address(trimmed)) {
      setWalletError('Invalid address. Must be a base58 string between 32 and 44 characters.');
      return;
    }
    setWalletError(null);
    setWalletSaving(true);
    setWalletSaved(false);
    try {
      await setPayoutWallet(trimmed === '' ? null : trimmed);
      setWalletSaved(true);
    } catch (err) {
      setWalletError(err instanceof Error ? err.message : 'Failed to save wallet address.');
    } finally {
      setWalletSaving(false);
    }
  }, [walletInput, setPayoutWallet]);

  const rewardTypeBadge =
    rewards?.rewardType === 'direct_payout' ? 'Direct Payout' : 'Credits';

  return (
    <div
      className={`cedros-rewards-panel ${className ?? ''}`.trim()}
      aria-label="Rewards dashboard"
    >
      {/* ---- error banner ---- */}
      {error && (
        <div className="cedros-rewards-panel__error" role="alert">
          {error.message}
        </div>
      )}

      {/* ---- Section 1: Summary Cards ---- */}
      <section
        className="cedros-rewards-panel__summary"
        aria-label="Rewards summary"
      >
        <div className="cedros-rewards-panel__card">
          <span className="cedros-rewards-panel__card-label">Total Earned</span>
          <span className="cedros-rewards-panel__card-value">
            {rewards ? formatAmount(rewards.totalEarned, rewards.currency) : '—'}
          </span>
        </div>

        <div className="cedros-rewards-panel__card">
          <span className="cedros-rewards-panel__card-label">Pending Payouts</span>
          <span className="cedros-rewards-panel__card-value">
            {rewards
              ? `${formatAmount(rewards.pendingAmount, rewards.currency)} (${rewards.pendingCount})`
              : '—'}
          </span>
        </div>

        <div className="cedros-rewards-panel__card">
          <span className="cedros-rewards-panel__card-label">Referrals</span>
          <span className="cedros-rewards-panel__card-value">
            {rewards ? String(rewards.referralCount) : '—'}
          </span>
        </div>

        <div className="cedros-rewards-panel__card">
          <span className="cedros-rewards-panel__card-label">Reward Type</span>
          <span className="cedros-rewards-panel__card-value">
            <span className="cedros-rewards-panel__type-badge">{rewardTypeBadge}</span>
          </span>
        </div>
      </section>

      {/* ---- Section 2: Payout Wallet (direct_payout only) ---- */}
      {rewards?.rewardType === 'direct_payout' && (
        <section
          className="cedros-rewards-panel__wallet-section"
          aria-label="Payout wallet"
        >
          <h3 className="cedros-rewards-panel__section-title">Payout Wallet</h3>

          <div className="cedros-rewards-panel__wallet-current">
            <span className="cedros-rewards-panel__wallet-label">Current address:</span>
            <span className="cedros-rewards-panel__wallet-address">
              {rewards.payoutWalletAddress ?? 'Not set'}
            </span>
          </div>

          <div className="cedros-rewards-panel__wallet-form">
            <label
              htmlFor="cedros-payout-wallet-input"
              className="cedros-rewards-panel__wallet-input-label"
            >
              Wallet address
            </label>
            <input
              id="cedros-payout-wallet-input"
              type="text"
              className="cedros-rewards-panel__wallet-input"
              value={walletInput}
              onChange={(e) => {
                setWalletInput(e.target.value);
                setWalletError(null);
                setWalletSaved(false);
              }}
              placeholder="Base58 Solana address"
              aria-describedby={walletError ? 'cedros-wallet-error' : undefined}
              disabled={walletSaving}
            />
            <button
              type="button"
              className="cedros-rewards-panel__wallet-save-btn"
              onClick={handleWalletSave}
              disabled={walletSaving || isLoading}
            >
              {walletSaving ? 'Saving...' : 'Save'}
            </button>
          </div>

          {walletError && (
            <div
              id="cedros-wallet-error"
              className="cedros-rewards-panel__wallet-error"
              role="alert"
            >
              {walletError}
            </div>
          )}

          {walletSaved && !walletError && (
            <div
              className="cedros-rewards-panel__wallet-success"
              role="status"
            >
              Wallet address saved.
            </div>
          )}
        </section>
      )}

      {/* ---- Section 3: History Table ---- */}
      <section
        className="cedros-rewards-panel__history-section"
        aria-label="Reward history"
      >
        <h3 className="cedros-rewards-panel__section-title">History</h3>

        {isLoading && history.length === 0 ? (
          <div className="cedros-rewards-panel__loading" aria-busy="true">
            Loading...
          </div>
        ) : history.length === 0 ? (
          <div className="cedros-rewards-panel__empty">No rewards yet.</div>
        ) : (
          <>
            <div className="cedros-rewards-panel__table-wrapper" role="region" aria-label="Reward history table" tabIndex={0}>
              <table className="cedros-rewards-panel__table">
                <thead>
                  <tr>
                    <th scope="col" className="cedros-rewards-panel__th">Date</th>
                    <th scope="col" className="cedros-rewards-panel__th">Type</th>
                    <th scope="col" className="cedros-rewards-panel__th">Amount</th>
                    <th scope="col" className="cedros-rewards-panel__th">Status</th>
                    <th scope="col" className="cedros-rewards-panel__th">Transaction</th>
                  </tr>
                </thead>
                <tbody>
                  {history.map((item) => (
                    <tr key={item.id} className="cedros-rewards-panel__tr">
                      <td className="cedros-rewards-panel__td">
                        {formatDate(item.createdAt)}
                      </td>
                      <td className="cedros-rewards-panel__td">
                        {triggerLabel(item.triggerType)}
                      </td>
                      <td className="cedros-rewards-panel__td">
                        {formatAmount(item.amount, item.currency)}
                      </td>
                      <td className="cedros-rewards-panel__td">
                        <StatusBadge status={item.status} />
                      </td>
                      <td className="cedros-rewards-panel__td">
                        {item.txSignature ? (
                          <a
                            href={`${explorerUrl}/tx/${item.txSignature}`}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="cedros-rewards-panel__tx-link"
                            aria-label={`View transaction ${item.txSignature.slice(0, 8)}... on Solana explorer`}
                          >
                            {item.txSignature.slice(0, 8)}...
                          </a>
                        ) : (
                          <span className="cedros-rewards-panel__tx-none">—</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* pagination */}
            {totalPages > 1 && (
              <div
                className="cedros-rewards-panel__pagination"
                role="navigation"
                aria-label="History pagination"
              >
                <button
                  type="button"
                  className="cedros-rewards-panel__page-btn"
                  onClick={() => handlePageChange(page - 1)}
                  disabled={page === 0 || isLoading}
                  aria-label="Previous page"
                >
                  Previous
                </button>
                <span className="cedros-rewards-panel__page-info">
                  {page + 1} / {totalPages}
                </span>
                <button
                  type="button"
                  className="cedros-rewards-panel__page-btn"
                  onClick={() => handlePageChange(page + 1)}
                  disabled={page >= totalPages - 1 || isLoading}
                  aria-label="Next page"
                >
                  Next
                </button>
              </div>
            )}
          </>
        )}
      </section>
    </div>
  );
}
