/**
 * Multi-step deposit flow component
 *
 * Provides a complete deposit wizard with configurable currency support:
 * - SOL only mode
 * - Single token mode (admin-configured token)
 * - Multi-token mode (user selects from allowed tokens)
 */

import { useState, useCallback, useEffect, useMemo, useRef } from 'react';
import { useDeposit } from '../../../hooks/useDeposit';
import { useWallet } from '../../../hooks/useWallet';
import type { Token } from '../tokens';
import { SOL_TOKEN, normalizeTokenSymbols } from './tokenUtils';
import { getTotalFeeUsd } from './feeUtils';
import { useDepositPolling } from './useDepositPolling';
import { ExplainerStep } from './steps/ExplainerStep';
import { UnlockStep } from './steps/UnlockStep';
import { ConfirmStep } from './steps/ConfirmStep';
import { SigningStep } from './steps/SigningStep';
import { ShowAddressStep } from './steps/ShowAddressStep';
import { WaitingStep } from './steps/WaitingStep';
import { SuccessStep } from './steps/SuccessStep';
import { ErrorStep } from './steps/ErrorStep';
import { StepIndicator } from './StepIndicator';
import type {
  DepositFlowProps,
  DepositFlowResult,
  DepositFlowStep,
  DepositMethod,
} from './types';

export type { CurrencyMode, DepositMethod, DepositFlowStep, ExplainerConfig, DepositFlowProps, DepositFlowResult } from './types';

/**
 * Multi-step deposit flow component
 */
export function DepositFlow({
  config,
  currencyMode,
  depositMethod: depositMethodProp,
  tokens = [],
  defaultToken,
  minAmount,
  maxAmount = 10000,
  onSuccess,
  onError,
  onCancel,
  onUnlockRequired,
  onAuthorize,
  className = '',
  showStepIndicator = true,
  pollInterval = 5000,
  demoMode = false,
  demoAutoConfirmMs,
  tokenPriceUsd,
  showExplainer = false,
  siteName,
  explainerConfig,
}: DepositFlowProps) {
  const { deposit, getStatus, error: depositError, clearError } = useDeposit();
  const wallet = useWallet();
  const quickActionSymbols = normalizeTokenSymbols(config.quickActionTokens);
  const customTokenSymbols = normalizeTokenSymbols(config.customTokenSymbols);

  // Merge preset tokens with admin-configured custom tokens
  const mergedTokens = useMemo(() => {
    const customDefs = config.customTokens ?? [];
    if (customDefs.length === 0) return tokens;

    const seen = new Set(tokens.map((t) => t.symbol));
    const merged = [...tokens];

    for (const def of customDefs) {
      if (!seen.has(def.symbol)) {
        merged.push({
          mint: def.mint,
          symbol: def.symbol,
          name: def.symbol,
          decimals: def.decimals,
          logoUrl: def.logoUrl,
        });
        seen.add(def.symbol);
      }
    }
    return merged;
  }, [tokens, config.customTokens]);

  // Filter merged tokens based on customTokenSymbols setting
  const customListTokens = useMemo(() => {
    if (customTokenSymbols.length === 0) return mergedTokens;
    const filtered = mergedTokens.filter((token) => customTokenSymbols.includes(token.symbol));
    return filtered.length > 0 ? filtered : mergedTokens;
  }, [mergedTokens, customTokenSymbols]);

  // Auto-detect deposit method if not specified
  const canUseSignMode = config.privateDepositsEnabled;
  const depositMethod: DepositMethod = depositMethodProp
    ? depositMethodProp === 'sign' && !canUseSignMode
      ? 'receive'
      : depositMethodProp
    : canUseSignMode && wallet.hasExternalWallet
      ? 'sign'
      : 'receive';

  // Determine effective token based on mode
  // Priority: defaultToken > first quick action token > USDC > first non-SOL > first token > SOL
  const firstQuickActionToken = quickActionSymbols[0]
    ? mergedTokens.find((t) => t.symbol === quickActionSymbols[0])
    : undefined;
  const effectiveToken =
    currencyMode === 'sol'
      ? SOL_TOKEN
      : currencyMode === 'single-token'
        ? (firstQuickActionToken ??
          mergedTokens.find((t) => t.symbol === 'USDC') ??
          mergedTokens[0] ??
          SOL_TOKEN)
        : (defaultToken ??
          firstQuickActionToken ??
          mergedTokens.find((candidate) => candidate.symbol === 'USDC') ??
          mergedTokens.find((candidate) => candidate.symbol !== 'SOL') ??
          mergedTokens[0] ??
          SOL_TOKEN);

  const getFirstStep = useCallback((): DepositFlowStep => {
    if (showExplainer) return 'explainer';
    return 'unlock';
  }, [showExplainer]);

  // State
  const [step, setStep] = useState<DepositFlowStep>(getFirstStep);
  const [selectedToken, setSelectedToken] = useState<Token>(effectiveToken);
  const [amount, setAmount] = useState<string>('');
  const [result, setResult] = useState<DepositFlowResult | null>(null);
  const [flowError, setFlowError] = useState<string | null>(null);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [depositAddress, setDepositAddress] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [isAuthorizing, setIsAuthorizing] = useState(false);
  const [receiveAmountUsd, setReceiveAmountUsd] = useState<number | null>(null);
  const copyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Clear copy timeout on unmount
  useEffect(() => {
    return () => {
      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
    };
  }, []);

  // Reset flow when currencyMode or depositMethod changes
  useEffect(() => {
    setStep(getFirstStep());
    setSelectedToken(effectiveToken);
    setAmount('');
    setResult(null);
    setFlowError(null);
    setSessionId(null);
    setDepositAddress(null);
    setCopied(false);
    setIsAuthorizing(false);
    setReceiveAmountUsd(null);
    clearError();
    // R2-M15: getFirstStep removed from deps to prevent spurious resets
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currencyMode, depositMethod, effectiveToken, clearError]);

  const effectiveMin = minAmount ?? config.privateMinSol;
  const effectiveMax = maxAmount;

  const parsedAmount = parseFloat(amount);

  // Wallet status
  const isEnrolled =
    wallet.status === 'enrolled_locked' ||
    wallet.status === 'enrolled_unlocked' ||
    wallet.status === 'unlocked';
  const walletReady = isEnrolled && wallet.isUnlocked;
  const needsUnlock = isEnrolled && !wallet.isUnlocked;

  const getSteps = useCallback((): { key: DepositFlowStep; label: string }[] => {
    const signSteps = [
      { key: 'unlock' as const, label: 'Authorize' },
      { key: 'confirm' as const, label: 'Send' },
      { key: 'signing' as const, label: 'Signing' },
      { key: 'success' as const, label: 'Complete' },
    ];

    const receiveSteps = [
      { key: 'unlock' as const, label: 'Authorize' },
      { key: 'show-address' as const, label: 'Send' },
      { key: 'waiting' as const, label: 'Confirming' },
      { key: 'success' as const, label: 'Complete' },
    ];

    let steps: { key: DepositFlowStep; label: string }[] =
      depositMethod === 'sign' ? signSteps : receiveSteps;

    if (showExplainer) {
      steps = [{ key: 'explainer', label: 'Info' }, ...steps];
    }

    return steps;
  }, [depositMethod, showExplainer]);

  const steps = getSteps();
  const currentStepIndex = steps.findIndex((s) => s.key === step);

  const handleTokenSelect = useCallback((token: Token) => {
    setSelectedToken(token);
  }, []);

  const handleAuthorize = useCallback(
    async (password: string) => {
      if (!onAuthorize) {
        setStep(depositMethod === 'sign' ? 'confirm' : 'show-address');
        return;
      }

      setIsAuthorizing(true);
      setFlowError(null);

      try {
        const authorizeAmount = depositMethod === 'sign' ? parsedAmount : null;
        const authResult = await onAuthorize(password, authorizeAmount, selectedToken);
        setSessionId(authResult.sessionId);
        setDepositAddress(authResult.depositAddress);
        setStep(depositMethod === 'sign' ? 'confirm' : 'show-address');
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Authorization failed');
        setFlowError(error.message);
      } finally {
        setIsAuthorizing(false);
      }
    },
    [onAuthorize, depositMethod, parsedAmount, selectedToken]
  );

  const handleDeposit = useCallback(
    async (depositAmount?: number, depositToken?: Token) => {
      clearError();
      setFlowError(null);
      setStep('signing');

      const finalAmount = depositAmount ?? parsedAmount;
      const finalToken = depositToken ?? selectedToken;

      if (!demoMode) {
        if (needsUnlock && onUnlockRequired) {
          onUnlockRequired();
          setStep('confirm');
          return;
        }

        if (!walletReady) {
          setFlowError('Wallet not ready');
          setStep('error');
          return;
        }
      }

      try {
        const smallestUnit = Math.round(finalAmount * Math.pow(10, finalToken.decimals));

        if (demoMode) {
          await new Promise((resolve) => setTimeout(resolve, 1500));
          const flowResult: DepositFlowResult = {
            token: currencyMode === 'sol' ? null : finalToken,
            amount: finalAmount,
            amountSmallestUnit: smallestUnit,
            txSignature: `demo-tx-${Date.now()}`,
            sessionId: sessionId || `demo-session-${Date.now()}`,
            response: {
              sessionId: sessionId || `demo-session-${Date.now()}`,
              txSignature: `demo-tx-${Date.now()}`,
              amountLamports: smallestUnit,
              message: 'Demo deposit successful',
              withdrawalAvailableAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
            },
            method: 'sign',
          };
          setResult(flowResult);
          setStep('success');
          onSuccess?.(flowResult);
          return;
        }

        const response = await deposit(smallestUnit);

        const flowResult: DepositFlowResult = {
          token: currencyMode === 'sol' ? null : finalToken,
          amount: finalAmount,
          amountSmallestUnit: smallestUnit,
          txSignature: response.txSignature,
          sessionId: response.sessionId,
          response,
          method: 'sign',
        };

        setResult(flowResult);
        setStep('success');
        onSuccess?.(flowResult);
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Deposit failed');
        setFlowError(error.message);
        setStep('error');
        onError?.(error);
      }
    },
    [
      deposit,
      parsedAmount,
      selectedToken,
      currencyMode,
      demoMode,
      sessionId,
      walletReady,
      needsUnlock,
      onUnlockRequired,
      onSuccess,
      onError,
      clearError,
    ]
  );

  const handleSentDeposit = useCallback(() => {
    setStep('waiting');
  }, []);

  const handleCopyAddress = useCallback(async () => {
    const address = depositAddress || wallet.solanaPubkey;
    if (address) {
      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
      try {
        await navigator.clipboard.writeText(address);
        setCopied(true);
        copyTimeoutRef.current = setTimeout(() => setCopied(false), 2000);
      } catch {
        const textArea = document.createElement('textarea');
        textArea.value = address;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);
        setCopied(true);
        copyTimeoutRef.current = setTimeout(() => setCopied(false), 2000);
      }
    }
  }, [depositAddress, wallet.solanaPubkey]);

  useDepositPolling({
    step,
    sessionId,
    demoMode,
    demoAutoConfirmMs,
    depositMethod,
    depositAddress,
    receiveAmountUsd,
    selectedToken,
    currencyMode,
    config,
    solanaPubkey: wallet.solanaPubkey,
    pollInterval,
    getStatus,
    onSuccess,
    setResult,
    setStep,
    setFlowError,
  });

  const handleReset = useCallback(() => {
    setStep(getFirstStep());
    setAmount('');
    setResult(null);
    setFlowError(null);
    clearError();
  }, [getFirstStep, clearError]);

  if (!config.enabled) {
    return (
      <div className={`cedros-deposit-flow cedros-deposit-flow-disabled ${className}`}>
        <p>Deposits are not currently available.</p>
      </div>
    );
  }

  const waitingFeeLine = receiveAmountUsd
    ? (() => {
        const f = getTotalFeeUsd(config, receiveAmountUsd);
        return f === 0 ? 'No fees' : `Fees: $${Math.max(f, 0.01).toFixed(2)} total`;
      })()
    : 'Fees: calculated after deposit';

  return (
    <div className={`cedros-deposit-flow ${className}`}>
      {showStepIndicator && step !== 'error' && (
        <StepIndicator steps={steps} currentStepIndex={currentStepIndex} currentStep={step} />
      )}

      {/* Step Content */}
      <div className="cedros-deposit-flow-content">
        {step === 'explainer' && (
          <ExplainerStep
            siteName={siteName}
            config={explainerConfig}
            depositConfig={config}
            currencyMode={currencyMode}
            token={selectedToken}
            tokens={customListTokens}
            onContinue={() => setStep('unlock')}
            onCancel={onCancel}
          />
        )}

        {step === 'unlock' && (
          <UnlockStep
            token={selectedToken}
            tokens={customListTokens}
            currencyMode={currencyMode}
            depositMethod={depositMethod}
            isAuthorizing={isAuthorizing}
            error={flowError}
            onAuthorize={handleAuthorize}
            onBack={showExplainer ? () => setStep('explainer') : undefined}
            onCancel={onCancel}
          />
        )}

        {step === 'confirm' && depositMethod === 'sign' && (
          <ConfirmStep
            token={selectedToken}
            tokens={mergedTokens}
            quickActionSymbols={quickActionSymbols}
            customTokenSymbols={customTokenSymbols}
            currencyMode={currencyMode}
            minAmount={effectiveMin}
            maxAmount={effectiveMax}
            depositAddress={depositAddress || wallet.solanaPubkey}
            walletReady={walletReady || demoMode}
            needsUnlock={needsUnlock && !demoMode}
            copied={copied}
            isListening={!!sessionId && !demoMode}
            config={config}
            onCopy={handleCopyAddress}
            onTokenSelect={handleTokenSelect}
            onUnlockRequired={onUnlockRequired}
            onConfirm={(amt, tkn) => handleDeposit(amt, tkn)}
            onBack={() => setStep('unlock')}
            onCancel={onCancel}
          />
        )}

        {step === 'signing' && <SigningStep depositAddress={wallet.solanaPubkey} />}

        {step === 'show-address' && (
          <ShowAddressStep
            token={selectedToken}
            tokens={mergedTokens}
            quickActionSymbols={quickActionSymbols}
            customTokenSymbols={customTokenSymbols}
            tokenPriceUsd={tokenPriceUsd}
            currencyMode={currencyMode}
            depositAddress={depositAddress || wallet.solanaPubkey}
            copied={copied}
            isListening={!!sessionId && !demoMode}
            config={config}
            onCopy={handleCopyAddress}
            onTokenSelect={handleTokenSelect}
            onAmountChange={setReceiveAmountUsd}
            onSent={handleSentDeposit}
            onBack={() => setStep('unlock')}
            onCancel={onCancel}
          />
        )}

        {step === 'waiting' && (
          <WaitingStep
            token={selectedToken}
            depositAddress={depositAddress || wallet.solanaPubkey}
            copied={copied}
            feeLine={waitingFeeLine}
            onCopy={handleCopyAddress}
          />
        )}

        {step === 'success' && result && (
          <SuccessStep result={result} config={config} onNewDeposit={handleReset} />
        )}

        {step === 'error' && (
          <ErrorStep
            error={flowError || depositError || 'An error occurred'}
            onRetry={() => setStep('confirm')}
            onCancel={onCancel}
          />
        )}
      </div>
    </div>
  );
}
